<?php
namespace App\Controllers;use App\Core\Database;
final class DashboardController{public function index():void{$db=Database::connection();$stats=['books'=>(int)$db->query('SELECT COUNT(*) FROM books')->fetchColumn(),'available'=>(int)$db->query('SELECT COALESCE(SUM(available_quantity),0) FROM books')->fetchColumn(),'borrowed'=>(int)$db->query('SELECT COUNT(*) FROM checkouts WHERE status="checked_out"')->fetchColumn(),'overdue'=>(int)$db->query('SELECT COUNT(*) FROM checkouts WHERE status="checked_out" AND due_date<CURDATE()')->fetchColumn()];$recent=$db->query('SELECT c.*,b.title,u.name user_name FROM checkouts c JOIN books b ON b.id=c.book_id JOIN users u ON u.id=c.user_id ORDER BY c.checked_out_at DESC LIMIT 8')->fetchAll();$title='Dashboard';require BASE_PATH.'/app/Views/dashboard/index.php';}}
